-- Project: Product Catalog Quality Audit
-- Purpose: Load Python validation findings into PostgreSQL.

-- Rebuild this table when reloading the latest validation results.
DROP TABLE IF EXISTS validation_issues;

CREATE TABLE validation_issues (
    source_category TEXT,
    source_file TEXT,
    barcode TEXT,
    product_name TEXT,
    field TEXT,
    issue_type TEXT,
    severity TEXT,
    observed_value TEXT,
    recommended_action TEXT
);

